import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { Resolucion, ResolucionGenerarResponse, SolicitudSnapshot } from '../models/resolucion.model';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class ResolucionService {
  private readonly http = inject(HttpClient);

  generar(folio: string, sentido: 'Autorizada' | 'No Autorizada'): Observable<ResolucionGenerarResponse> {
    return this.http.post<ResolucionGenerarResponse>(
      `${environment.apiUrl}/solicitudes/${folio}/resolucion/generar`,
      { sentido },
    );
  }

  firmar(folio: string, resolucionId: number, signedPdf: Uint8Array, metadata?: string): Observable<void> {
    const formData = new FormData();
    formData.append('resolucion_id', resolucionId.toString());
    const blob = new Blob([signedPdf.buffer as ArrayBuffer], { type: 'application/pdf' });
    formData.append('signed_pdf', blob, 'resolucion_firmada.pdf');
    if (metadata) {
      formData.append('firma_metadata', metadata);
    }
    return this.http.post<void>(
      `${environment.apiUrl}/solicitudes/${folio}/resolucion/firmar`,
      formData,
    );
  }

  transicion(folio: string, status: string): Observable<void> {
    return this.http.post<void>(
      `${environment.apiUrl}/solicitudes/${folio}/transicion`,
      { status },
    );
  }

  getResolucion(id: number): Observable<Resolucion> {
    return this.http.get<{ data: Resolucion }>(
      `${environment.apiUrl}/resoluciones/${id}`,
    ).pipe(
      map(response => response.data),
    );
  }

  getResoluciones(folio: string): Observable<Resolucion[]> {
    return this.http.get<{ data: Resolucion[] }>(
      `${environment.apiUrl}/solicitudes/${folio}/resoluciones`,
    ).pipe(
      map(response => response.data),
    );
  }

  getHistorial(folio: string): Observable<SolicitudSnapshot[]> {
    return this.http.get<{ data: Record<string, unknown>[] }>(
      `${environment.apiUrl}/solicitudes/${folio}/historial`,
    ).pipe(
      map(response => response.data.map(item => ({
        id: item['id'] as number,
        createdAt: item['created_at'] as string,
        data: item['data'] as SolicitudSnapshot['data'],
        resolucion: item['resolucion'] as SolicitudSnapshot['resolucion'],
      }))),
    );
  }

  getSnapshotById(id: number): Observable<SolicitudSnapshot> {
    return this.http.get<{ data: SolicitudSnapshot }>(
      `${environment.apiUrl}/solicitudes/snapshots/${id}`,
    ).pipe(
      map(response => response.data),
    );
  }

  descargarResolucion(folio: string, id: number): Observable<Blob> {
    return this.http.get(
      `${environment.apiUrl}/solicitudes/${folio}/resoluciones/${id}/descargar`,
      { responseType: 'blob' },
    );
  }
}
